package org.jsoup.nodes;

import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class ScratchFormTest {
    @Test public void fosterParentedControlsAppearOnceInDocumentOrder() {
        // input foster-parented out of the table, before it; form is inside the table
        String html = "<table><form id=f><input name=a value=1></form></table>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("a=1", data.get(0).toString());
        assertEquals(1, form.elements().size());
    }

    @Test public void linkedControlOrderMergesWithDescendants() {
        // form inside table; inputs stay in cells (linked), submit input is a descendant
        String html = "<form id=f><input name=first value=1><table><tr><td><input name=second value=2></td></tr></table><input name=third value=3></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(3, data.size());
        assertEquals("first=1", data.get(0).toString());
        assertEquals("second=2", data.get(1).toString());
        assertEquals("third=3", data.get(2).toString());
    }

    @Test public void removedOrReassociatedControlsDropOldValues() {
        String html = "<form id=f><input name=a value=1><input name=b value=2></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        assertEquals(2, form.formData().size());

        doc.selectFirst("input[name=a]").remove();
        assertEquals(1, form.formData().size());
        assertEquals("b=2", form.formData().get(0).toString());

        doc.selectFirst("input[name=b]").attr("form", "other");
        assertTrue(form.formData().isEmpty());
    }

    @Test public void sameNameValuesKeptInOrder() {
        String html = "<form><input name=x value=1><input name=x value=2><input name=x value=3></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(3, data.size());
        assertEquals("1", data.get(0).value());
        assertEquals("2", data.get(1).value());
        assertEquals("3", data.get(2).value());
    }

    @Test public void documentNotMutatedByFormData() {
        String html = "<form id=f><fieldset disabled><legend><input name=a value=1></legend><input name=b value=2></fieldset><select name=s><option value=o1 selected><option value=o2></select></form>";
        Document doc = Jsoup.parse(html);
        String before = doc.html();
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(2, data.size());
        assertEquals("a=1", data.get(0).toString());
        assertEquals("s=o1", data.get(1).toString());
        assertEquals(before, doc.html());
        // and still queryable
        assertNotNull(doc.selectFirst("form#f"));
    }

    @Test public void emptyFormGivesEmptyData() {
        Document doc = Jsoup.parse("<form></form>");
        FormElement form = (FormElement) doc.selectFirst("form");
        assertTrue(form.formData().isEmpty());
        assertTrue(form.elements().isEmpty());
    }

    @Test public void nestedDisabledFieldsetLegendException() {
        // control in first legend of inner enabled fieldset, inside disabled outer fieldset, not in outer's legend
        String html = "<form><fieldset disabled><legend><input name=a value=1></legend>" +
            "<fieldset><input name=b value=2></fieldset></fieldset></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("a=1", data.get(0).toString());
    }

    @Test public void disabledOptgroupOptionNotSubmitted() {
        String html = "<form><select name=s><optgroup disabled><option value=a selected></optgroup><option value=b></select></form>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("s=b", data.get(0).toString());
    }
}

